from taf.ul.kpi_selector.operations.cell_lock.classical_cell_lock.cell_lock_prototype import CellLock


class CellLock23R1(CellLock):

    def get_kpi(self):
        """
        Gets kpi for cell lock operation.
        :return: dictionary with timeout, requirement and operation description for cell lock
        :rtype: dict
        """

        if all(
                [
                    self.check_smod_bbmod_types(smod_type="ASIL", bbmod_types=["ABIP"]),
                    self.bts.number_of_bbmods == 1,
                    self.bts.number_of_nr_cells <= 2,
                    self.bts.number_of_rmods <= 2,
                    self.bts.cell_technologies == "TDD",
                    self.bts.setup_mode == "NSA",
                    self.bts.radio_protocol == "eCPRI",
                    "AZQP" in self.bts.rmod_hw_types
                ]
        ):
            self.operation_details["Timeout"] = 30
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.17146"

        elif all(
                [
                    self.check_smod_bbmod_types(smod_type="ASIM", bbmod_types=["ABIP"]),
                    self.bts.number_of_bbmods == 1,
                    self.bts.number_of_nr_cells <= 2,
                    self.bts.number_of_rmods <= 2,
                    self.bts.cell_technologies == "TDD",
                    self.bts.setup_mode == "NSA",
                    self.bts.radio_protocol == "eCPRI",
                    "AQQL" in self.bts.rmod_hw_types or "AEQE" in self.bts.rmod_hw_types,
                ]
        ):
            self.operation_details["Timeout"] = 30
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.17159"

        elif all(
                [
                    self.check_smod_bbmod_types(smod_type="ASIM", bbmod_types=["ABIP"]),
                    self.bts.number_of_bbmods == 1,
                    self.bts.number_of_nr_cells <= 3,
                    self.bts.number_of_rmods <= 3,
                    self.bts.cell_technologies == "FDD",
                    self.bts.setup_mode == "SA",
                    self.bts.radio_protocol == "CPRI",
                    any(["AHEGB" in self.bts.rmod_hw_types,
                         "AHEH" in self.bts.rmod_hw_types,
                         "AHLOA" in self.bts.rmod_hw_types]),
                ]
        ):
            self.operation_details["Timeout"] = 30
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.17172"

        elif all(
                [
                    self.check_smod_bbmod_types(smod_type="ASIL", bbmod_types=["ABIP"]),
                    self.bts.number_of_bbmods == 1,
                    self.bts.is_multi_rat,
                    self.bts.number_of_nr_cells <= 3,
                    self.bts.number_of_lte_cells <= 3,
                    self.bts.cell_technologies == "FDD",
                    self.bts.setup_mode == "NSA",
                    self.bts.radio_protocol == "CPRI",
                ]
        ):
            self.operation_details["Timeout"] = 30
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.19750"

        elif all(
                [
                    self.check_smod_bbmod_types(smod_type="ASIL", bbmod_types=["ABIP"]),
                    self.bts.number_of_bbmods == 1,
                    self.bts.number_of_nr_cells <= 4,
                    self.bts.cell_technologies == "MIX",
                    self.bts.setup_mode == "NSA",
                ]
        ):
            self.operation_details["Timeout"] = 30
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.19776"

        else:
            return super(CellLock23R1, self).get_kpi()

        return self.operation_details
